<?php $extend('beheer', ['title' => 'Producten']); ?>
<div class="page-head"><div class="ph-icon"><?= icon('box') ?></div><div class="ph-text"><h1>Producten &amp; pakketten</h1><div class="sub">Wat je verkoopt: domeinextensies, pakketten en andere producten<?= $kind !== '' ? ' · ' . e(\App\Models\Product::soortLabel($kind)) : '' ?><?php if ($kind !== ''): ?> · <a href="<?= e(url('/beheer/producten')) ?>">alle producten</a><?php endif; ?></div></div><a class="btn" href="<?= e(url('/beheer/producten/nieuw' . ($kind !== '' ? '?soort=' . rawurlencode($kind) : ''))) ?>"><?= icon('plus', 'icon icon-sm') ?> Nieuw product</a></div>
<div class="card"><?php if ($products === []): ?><div class="empty">Nog geen producten.</div><?php else: ?>
<div class="table-wrap"><table class="table"><thead><tr><th>Nummer</th><th>Product</th><th>Prijs</th><th>Instelkosten</th><th>Uitgelicht</th><th>Zichtbaar</th></tr></thead><tbody>
<?php foreach ($products as $p): ?><tr><td class="mono"><?= e($p->Nummer) ?></td><td><a class="cell-product" href="<?= e(url('/beheer/producten/' . $p->id())) ?>"><span class="cell-tile"><?= icon(\App\Models\Product::GROUPS[$p->Groep] ?? 'box', 'icon icon-sm') ?></span><span><strong><?= e($p->Naam) ?></strong><span class="small muted"><?= e(\App\Models\Product::soortLabel($p->Dienstsoort) ?: $p->Groep) ?> · <?= e($p->path()) ?></span></span></a></td>
<td class="nowrap"><?= e(money((int) $p->Prijs)) ?> <span class="small muted"><?= e(period_label((string) $p->Periode)) ?></span></td><td><?= (int) $p->Instelkosten ? e(money((int) $p->Instelkosten)) : '-' ?></td>
<td><?= check_icon((bool) $p->Uitgelicht) ?></td><td><?= check_icon((bool) $p->Zichtbaar) ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></div>
